import {afterEach,expect,it,vi} from 'vitest'
import {qualityTrack} from '../metric-upstream/continuous/qualityFixture'
import fs from 'node:fs'
import zlib from 'node:zlib'
import {MetricRun} from './metric'
import {nearbyPlan} from './nearby'
import {choiceForPlan,rankNearbyChoices} from './smart-selection'
import * as preparation from './device-prepare'
import type {Track} from '../metric-upstream/realtime/planner'
import type {DevicePrepared} from './device-execution'

afterEach(()=>vi.restoreAllMocks())
it('the HIPHOP to Make It Right successor covers a tap delivered after the first cue',()=>{
 const tracks:Track[]=JSON.parse(zlib.gunzipSync(fs.readFileSync(new URL('./fixtures/handoff-quality-real.json.gz',import.meta.url))).toString()).tracks
 const a=tracks.find(t=>t.title==='HIPHOP')!,b=tracks.find(t=>t.title==='Make It Right')!
 const first=rankNearbyChoices(a,[b],68.9,3).best!
 expect(first).not.toBeNull()
 const successor=rankNearbyChoices(a,[b],first.plan.start+.001,3).best!
 const delivered=rankNearbyChoices(a,[b],71.63,3).best!
 expect(first.plan.start).toBeLessThan(71.63)
 expect(successor).not.toBeNull();expect(delivered).not.toBeNull()
 expect(successor.plan.id).toBe(delivered.plan.id)
 expect(successor.plan.start).toBeGreaterThan(first.plan.start)
})
it.each([{advance:false,approved:false,name:'current nearest cue'},{advance:true,approved:false,name:'next adjacent cue after playback advances'},{advance:false,approved:true,name:'current nearest cue after an approved reservation point warms first'},{advance:true,approved:true,name:'next adjacent cue after an approved reservation point warms first'}])('reuses rolling PCM for $name without moving the manual selection',async({advance,approved})=>{
 const a=qualityTrack('a'),b=qualityTrack('b')
 b.windows[0].variants={...b.windows[0].variants,unrelated:{...b.windows[0].variants.a,url:'not-in-this-set'}}
 const tracks=[a,b],index:any={schema:'harbeat.continuous-library.v1',tracks:tracks.map(t=>({...t,detailUrl:t.id,collection:'NAS',styleLabels:['Hip-Hop'],playStatus:'ready',mixStatus:'ready'}))}
 const p:any={localExecution:true,ctx:{sampleRate:44100,resume:async()=>{}},initialize:async()=>{},current:null,position:20,playing:true,paused:false,busy:false,transition:null,logs:[],cache:{ready:new Set()},start:async(t:Track)=>{p.current=t},setVolume:()=>{},stop:()=>{},dispose:()=>{},export:()=>({}),arm:vi.fn(async(result:any)=>{p.transition={result}})}
 const render=vi.spyOn(preparation,'prepareDevice').mockImplementation(async(_p,a,b,plan)=>({schema:'harbeat.device-execution-plan.v1',id:plan.id,status:'ready',plan:{from:a.id,to:b.id,start:plan.start,end:plan.end,duration:plan.duration,rate:plan.rate,bStart:plan.window.start,bEnd:plan.window.end,windowId:plan.window.id,beatErrorMs:0},execution:{schema:'harbeat.device-execution-plan.v1'},assets:{},decision:{recommended:'original',methods:{original:{eligible:true,name:'原渐混'}}}} as DevicePrepared))
 vi.spyOn(preparation,'hasDevicePCM').mockReturnValue(true)
 vi.spyOn(preparation,'pinDevicePCM').mockReturnValue(()=>{})
 vi.spyOn(preparation,'preloadDevice').mockResolvedValue(undefined as any)
 vi.spyOn(preparation,'loadPrepared').mockResolvedValue(undefined)
 const run=new MetricRun(index,new URL('https://test.local/'),()=>{},undefined,()=>p,async id=>({track:tracks.find(t=>t.id===id)}))
 try{
  await run.start(a.id);run.choose(b.id)
  const retainedB={...b,windows:b.windows.map(w=>({...w,variants:{a:w.variants.a}}))}
  // Deliberately sparse cloud samples: the actual manual material must still
  // be generated by the unchanged live planner at the current source time.
  const selected=nearbyPlan(a,b,p.position,new Set(),plan=>!!choiceForPlan(a,b,plan,3),plan=>choiceForPlan(a,b,plan,3)?.score??-Infinity)!
  expect(selected).not.toBeNull();expect(selected.start).toBeGreaterThan(21.5)
  const approvedPlan=rankNearbyChoices(a,[retainedB],selected.start+8,3).best!.plan
  expect(approvedPlan.start).toBeGreaterThan(selected.start)
  ;(run as any).activity={packId:'set',name:'set',ids:new Set(['a','b']),tracks:[a,retainedB],results:[],candidateCount:24,cloudCoverage:{schema:'test'},candidates:()=>[],approvedCandidates:()=>approved?[{track:retainedB,plan:approvedPlan}]:[]}
  ;(run as any).warmNearby()
  await vi.waitFor(()=>{expect(run.snapshot().warm.state,JSON.stringify(p.logs)).toBe('ready');expect(run.snapshot().warm.ready.length).toBeGreaterThan(0)})
  expect(selected).not.toBeNull();expect(run.snapshot().warm.ready.some(c=>c.start===selected.start)).toBe(true)
  if(approved){expect(render.mock.calls[0][3].id).toBe(approvedPlan.id);expect(run.snapshot().warm.ready.some(c=>c.start===approvedPlan.start)).toBe(true);expect(render).toHaveBeenCalledTimes(3)}
  if(advance)p.position=selected.start+.01
  const actual=nearbyPlan(a,b,p.position,new Set(),plan=>!!choiceForPlan(a,b,plan,3),plan=>choiceForPlan(a,b,plan,3)?.score??-Infinity)!
  expect(actual).not.toBeNull()
  if(advance){expect(actual.start).toBeGreaterThan(selected.start);expect(run.snapshot().warm.ready.some(c=>c.start===actual.start)).toBe(true)}
  const count=render.mock.calls.length
  await run.mixSoon()
  expect(p.arm).toHaveBeenCalledTimes(1);expect(p.arm.mock.calls[0][0].plan.start).toBe(actual.start)
  expect(render).toHaveBeenCalledTimes(count)
  expect(p.logs.some((row:any)=>row.kind==='device_prepared_reused')).toBe(true)
  expect(run.snapshot().activitySet?.prepared).toBe(24)
 }finally{run.dispose()}
})
